import sim, numpy as np

def eval_cfg(c2,c7,cT,steps=1000):
    s=sim.Sim(); a=s.home_ctrl()
    a[2]+=c2; a[7]+=c7; a[10]+=cT
    a=np.clip(a,s.model.actuator_ctrlrange[:,0],s.model.actuator_ctrlrange[:,1])
    for t in range(steps):
        s.data.ctrl[:] = a
        s.step()
    p=s.pelvis_position(); b=s.box_position();
    return p[0],b[0],p[2],b[2],s.torso_up(),np.linalg.norm(p-b)

cvals=np.linspace(-30,30,13)
# coarse scan around hip pitch -20
for cT in [-80,-40,-20,-10,0,10,20,40,80]:
    best=None
    for c2 in cvals:
        for c7 in cvals:
            x,bx,pz,bz,tu,bd=eval_cfg(c2,c7,cT)
            score=(x if tu>=0.5 else -1e3) + 0.5*(0.5-tu if tu<0.5 else 0)
            if best is None or score>best[0]:
                best=(score,(c2,c7),x,bx,pz,bz,tu,bd)
    print('torso',cT,'best',best)
PY"
